#define CACHE_LINE_SIZE 64

// 1. Spatial Locality (Sequential Memory Access)
#define N 100
int matrix[N][N];

// Excellent Spatial Locality (Row-Major access in C/C++)
// Loads cache line containing several adjacent matrix elements
for (int i = 0; i < N; ++i) {
    for (int j = 0; j < N; ++j) {
        matrix[i][j] *= 2; // Data accessed sequentially (fast)
    }
}
// Note: Column-major access (matrix[j][i]) degrades spatial locality dramatically

// ----------------------------------------------------

// 2. Mitigating False Sharing (Cache Line Padding/Alignment)
// False Sharing: Unrelated data used by different threads share one cache line
// Fix: Use alignment to guarantee separate cache lines
struct alignas(CACHE_LINE_SIZE) ThreadCounter {
    long hits;
    // PADDING implicitly added up to 64 bytes
};

ThreadCounter core_stats[4]; 

// Thread 1 accesses core_stats[0].hits
// Thread 2 accesses core_stats[1].hits
// No cache line invalidation required between threads

// ----------------------------------------------------

// 3. Temporal Locality (Data Reuse)
// Data recently accessed is stored in L1 cache (fastest access)
int sum = 0;
int x = 5; 
int y = 10;

// High Temporal Locality: x and y reused frequently
for (int i = 0; i < 1000; ++i) {
    if (i % 2 == 0) {
        sum += x;
    } else {
        sum += y;
    }
}
// Variables x, y likely remain resident in L1 cache for the loop duration
